以下函数 check()用于判断一棵二叉树是否为()。
```cpp
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val=val
        self.left = left
        self.right = right
from collections import deque
def check(root):
    if not root:
        return True
    q = deque()
    q.append(root)
    has_null = False
    while q:
        cur=q.popleft()
        if not cur:
            has_null = True
        else:
            if has_null:
                return False
            q.append(cur.left)
            q.append(cur.right)
    return True
```

以下函数实现了二叉排序树(BST)的()操作。
```cpp
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val= val
        self.left = left
        self.right = right
def op(root, x):
    if not root:
        return TreeNode(x)
    if x < root.val:
        root.left = op(root.left, x)
    else:
        root.right= op(root.right, x)
    return root
```

